      /^[ \t ]+time\b/i.test(afterTarget) &&
      /\b(?:take|takes|took|taken|taking|bide|bides|bided)[ \t ]+$/i.test(
        ctx.text.slice(Math.max(0, span[0] - 12), span[0]),
      )
